360		}
361		if msg := stderr.String(); !strings.Contains(msg, `context.plan: duplicate field "plan"`) {
362			t.Fatalf("duplicate field: stderr=%q", msg)
363		}
364	
365		// 无效的数字写法（1e+ 缺指数数字）仍是 JSON 语法错误，与大数字类型错误区分。
366		h = newHarness(t, bigNumberConfig, `{"plan":1e+}`)
367		stdout.Reset()
368		stderr.Reset()
369		if code := run(h.evalArgs("feature-big"), &stdout, &stderr); code == 0 {
370			t.Fatalf("malformed number: expected non-zero exit")
371		}
372		if stdout.Len() != 0 {
373			t.Fatalf("malformed number: stdout must be empty: %q", stdout.String())
374		}
375		if msg := stderr.String(); !strings.Contains(msg, "invalid JSON") ||
376			strings.Contains(msg, "value must be a string") {
377			t.Fatalf("malformed number must be a syntax error: stderr=%q", msg)
378		}
379	
380		// 修正为加引号的合法字符串后，按原文命中 eq 规则：stdout 为单个 JSON 对象，
381		// 含开关键、布尔结果、命中原因与规则编号；stderr 为空。
382		h = newHarness(t, bigNumberConfig, `{"plan":"1e400"}`)
383		stdout.Reset()
384		stderr.Reset()
385		if code := run(h.evalArgs("feature-big"), &stdout, &stderr); code != 0 {
386			t.Fatalf("quoted big number: exit=%d stderr=%s", code, stderr.String())
387		}
388		if stderr.Len() != 0 {
389			t.Fatalf("quoted big number: stderr must be empty: %q", stderr.String())
390		}
391		out := stdout.String()
392		if strings.Count(strings.TrimSpace(out), "\n") != 0 {
393			t.Fatalf("stdout must contain exactly one JSON object line: %q", out)
394		}
395		var got map[string]any
396		if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
397			t.Fatalf("stdout is not a single JSON object: %q (%v)", out, err)
398		}
399		if got["key"] != "feature-big" || got["value"] != true ||
400			got["reason"] != "rule" || got["ruleId"] != "r-big" {
401			t.Fatalf("unexpected payload: %v", got)
402		}
403	
404		// 合法字符串但未命中：回到默认值行为，规则编号为 null。
405		h = newHarness(t, bigNumberConfig, `{"plan":"1e401"}`)
406		stdout.Reset()
407		stderr.Reset()
408		if code := run(h.evalArgs("feature-big"), &stdout, &stderr); code != 0 {
409			t.Fatalf("non-matching string: exit=%d stderr=%s", code, stderr.String())
410		}
411		if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
412			t.Fatalf("non-matching output: %q (%v)", stdout.String(), err)
413		}
414		if got["value"] != false || got["reason"] != "default" || got["ruleId"] != nil {
415			t.Fatalf("non-matching string must fall through to default: %v", got)
416		}
417	
418		// 关闭开关配合合法字符串仍固定 disabled，不因上下文变为合法而启用。
419		h = newHarness(t, bigNumberConfig, `{"plan":"1e400"}`)
420		stdout.Reset()
421		stderr.Reset()
422		if code := run(h.evalArgs("feature-off"), &stdout, &stderr); code != 0 || stderr.Len() != 0 {
423			t.Fatalf("disabled flag: exit=%d stderr=%q", code, stderr.String())
424		}
425		if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
426			t.Fatalf("disabled output: %q", stdout.String())
427		}
428		if got["value"] != false || got["reason"] != "disabled" || got["ruleId"] != nil {
429			t.Fatalf("disabled flag must stay disabled with valid context: %v", got)
430		}
