806	// TestCLIEvaluateNameEscapeSpellingsEquivalent 验证同一个名字无论写成直接
807	// UTF-8 字符、合法 \uXXXX 转义还是两者混合，读入后都按解码文字识别：用解码后
808	// 的开关键请求时找到同一个开关，同一上下文命中同一条规则，布尔结果与原因一致，
809	// 结果中的 key 与 ruleId 还原为同一名称。名称同时含普通文字（é，BMP 内单个
810	// \u00E9）与必须完整代理项配对才能表示的字符（🚀 = \uD83D\uDE80）。
811	func TestCLIEvaluateNameEscapeSpellingsEquivalent(t *testing.T) {
812		const (
813			decodedKey = "café🚀"
814			decodedID  = "r-é🚀"
815		)
816		keySpellings := []struct{ name, json string }{
817			{"direct", `café🚀`},
818			{"escaped", `caf\u00E9\uD83D\uDE80`},
819			{"mixed", `caf\u00E9🚀`},
820		}
821		idSpellings := []struct{ name, json string }{
822			{"direct", `r-é🚀`},
823			{"escaped", `r-\u00E9\uD83D\uDE80`},
824			{"mixed", `r-é\uD83D\uDE80`},
825		}
826		var reference string // 直接写法的 stdout 原文，其余写法必须逐字节一致
827		for _, ks := range keySpellings {
828			for _, is := range idSpellings {
829				t.Run("key="+ks.name+"/id="+is.name, func(t *testing.T) {
830					h := newHarness(t, escapeNameConfig(ks.json, is.json), `{"plan":"pro"}`)
831					got, raw := evalSuccess(t, h, decodedKey)
832					if got["key"] != decodedKey || got["value"] != true ||
833						got["reason"] != "rule" || got["ruleId"] != decodedID {
834						t.Fatalf("unexpected payload: %v", got)
835					}
836					// 结果中的名称是解码后的文字本身，不是转义写法。
837					if !strings.Contains(raw, decodedKey) || !strings.Contains(raw, decodedID) {
838						t.Fatalf("stdout must carry the decoded names: %q", raw)
839					}
840					if ks.name == "direct" && is.name == "direct" {
841						reference = raw
842					} else if raw != reference {
843						t.Fatalf("spelling changed output:\n%s\n!= reference:\n%s", raw, reference)
844					}
845				})
846			}
847		}
848	}
