1019			value bool
1020		}{
1021			{"feature-a", false},
1022			{"Feature-A", true},
1023			{" feature-a", true},
1024			{"feature-a ", true},
1025			{"café", false},
1026			{"cafe\u0301", true}, // e + 组合符 U+0301，与预组合的 "café" 不是同一个名字
1027			{"p\u0430y", false},  // 西里尔 а（U+0430）
